@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase small fw-bold">Settings</h5>
    <nav class="nav flex-column">
        @foreach (var section in Sections)
        {
            <button class="nav-link settings-nav-item @(ActiveSection == section ? "active" : "")"
                    @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="me-2">@GetIcon(section)</span>
                @section
            </button>
        }
    </nav>
</div>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    min-height: 100%;
    padding-top: 0.5rem;
}

.settings-nav-item {
    border: none;
    background: none;
    text-align: left;
    padding: 0.6rem 1rem;
    margin: 0.15rem 0.5rem;
    border-radius: 0.375rem;
    color: #495057;
    cursor: pointer;
    font-size: 0.95rem;
    transition: background-color 0.15s;
}

.settings-nav-item:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-nav-item.active:hover {
    background-color: #0b5ed7;
}

@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="card">
    <div class="card-header d-flex justify-content-between align-items-center">
        <h5 class="mb-0">Profile</h5>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_successMessage))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_successMessage
                    <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-3 text-center mb-3">
                    <div class="avatar-preview mb-2">
                        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120" />
                    </div>
                    <small class="text-muted text-break">@_avatarUrl</small>
                </div>
                <div class="col-md-9">
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Display Name</label>
                        <input type="text" class="form-control" @bind="_displayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Email</label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-semibold">Bio</label>
                        <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                    </div>
                </div>
            </div>

            <div class="d-flex gap-2 justify-content-end">
                <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@_saving">
                    Discard Changes
                </button>
                <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save Changes
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
