@code {
    [Inject] private ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
        _loading = false;
    }

    private void ToggleChannel(string name, bool isMuted)
    {
        var ch = _channels.FirstOrDefault(c => c.Name == name);
        if (ch is not null)
        {
            ch.IsMuted = isMuted;
        }
    }

    private async Task SavePreferences()
    {
        _saving = true;
        _successMessage = null;
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _successMessage = "Notification preferences saved!";
        _saving = false;
    }

    private class ChannelState(string name, bool isMuted)
    {
        public string Name { get; set; } = name;
        public bool IsMuted { get; set; } = isMuted;
    }
}

