@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Notifications</h5>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_successMessage))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_successMessage
                    <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
                </div>
            }

            <h6 class="fw-semibold mb-3">General</h6>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>

            <hr />
            <h6 class="fw-semibold mb-3">Muted Channels</h6>
            <p class="text-muted small">Uncheck a channel to receive notifications from it.</p>

            @foreach (var channel in _channels)
            {
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel.Name}")"
                           checked="@channel.IsMuted"
                           @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel.Name}")">
                        #@channel.Name
                    </label>
                </div>
            }

            <div class="d-flex justify-content-end mt-3">
                <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save Preferences
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
        _loading = false;
    }

    private void ToggleChannel(string name, bool isMuted)
    {
        var ch = _channels.FirstOrDefault(c => c.Name == name);
        if (ch is not null)
        {
            ch.IsMuted = isMuted;
        }
    }

    private async Task SavePreferences()
    {
        _saving = true;
        _successMessage = null;
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _successMessage = "Notification preferences saved!";
        _saving = false;
    }

    private class ChannelState(string name, bool isMuted)
    {
        public string Name { get; set; } = name;
        public bool IsMuted { get; set; } = isMuted;
    }
}

