@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="card">
    <div class="card-header">
        <h6 class="mb-0">Active Sessions</h6>
    </div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th class="text-end">Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>
                                @session.Device
                                @if (session.Id == CurrentSessionId)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td class="text-end">
                                @if (session.Id != CurrentSessionId)
                                {
                                    @if (_confirmingSessionId == session.Id)
                                    {
                                        <span class="me-2 text-danger small">Revoke this session?</span>
                                        <button class="btn btn-sm btn-danger me-1" @onclick="() => ConfirmRevoke(session.Id)" disabled="@_revoking">
                                            Yes
                                        </button>
                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">
                                            No
                                        </button>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string CurrentSessionId { get; set; } = "sess-1";

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;
    private bool _revoking;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _revoking = true;
        await OnRevoke.InvokeAsync(sessionId);
        _confirmingSessionId = null;
        _revoking = false;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

