@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Security</h5>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <div class="mb-4">
                <ChangePasswordPanel OnPasswordChanged="ReloadSettings" />
            </div>

            <div class="card mb-4">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center">
                        <div>
                            <h6 class="mb-1">Two-Factor Authentication</h6>
                            <small class="text-muted">
                                @if (_twoFactorEnabled)
                                {
                                    <span class="text-success">● Enabled</span>
                                }
                                else
                                {
                                    <span class="text-danger">● Disabled</span>
                                }
                            </small>
                        </div>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="twoFactor"
                                   checked="@_twoFactorEnabled"
                                   @onchange="Toggle2FA" />
                        </div>
                    </div>
                    @if (_lastPasswordChange.HasValue)
                    {
                        <small class="text-muted d-block mt-2">
                            Last password change: @_lastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </small>
                    }
                </div>
            </div>

            <ActiveSessionsTable Sessions="_sessions" OnRevoke="RevokeSession" />
        }
    </div>
</div>

@code {
    [Inject] private ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
        _loading = false;
    }

    private async Task LoadSettings()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        await LoadSettings();
    }

    private async Task ReloadSettings()
    {
        await LoadSettings();
    }
}

