@using sv_07568ea01573471a82e7c632763e4624.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Appearance</h5>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_successMessage))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_successMessage
                    <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-7">
                    <h6 class="fw-semibold mb-3">Theme</h6>
                    <div class="mb-4">
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <h6 class="fw-semibold mb-3">Font Size</h6>
                    <div class="mb-4">
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <h6 class="fw-semibold mb-3">Language</h6>
                    <div class="mb-4">
                        <select class="form-select" style="max-width: 250px;"
                                @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>

                    <div class="form-check form-switch mb-4">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <div class="col-md-5">
                    <h6 class="fw-semibold mb-3">Preview</h6>
                    <div class="preview-area rounded border @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <div class="preview-header p-2 border-bottom">
                            <strong>Sample Header</strong>
                        </div>
                        <div class="@GetPreviewBodyPadding()">
                            <p class="mb-2">This is a preview of your selected appearance settings.</p>
                            <p class="mb-2 text-muted">Secondary text appears like this.</p>
                            <button class="btn btn-sm btn-primary">Sample Button</button>
                        </div>
                    </div>
                </div>
            </div>

            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _successMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _successMessage = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        return _theme == "Dark" ? "bg-dark text-light" : "bg-white text-dark";
    }

    private string GetPreviewStyles()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size}; min-height: 200px;";
    }

    private string GetPreviewBodyPadding()
    {
        return _compactMode ? "p-2" : "p-3";
    }
}

