@page "/settings"
@using sv_07568ea01573471a82e7c632763e4624.Components.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-sidebar-panel">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />
    </div>
    <div class="settings-content-panel">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 7rem);
    margin: -1rem -1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

.settings-sidebar-panel {
    flex: 0 0 220px;
    min-width: 220px;
}

.settings-content-panel {
    flex: 1;
    padding: 1.5rem;
    overflow-y: auto;
}

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar-panel {
        flex: none;
        min-width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
    }
}

